#include <AccelStepper.h>

// Step/direction driver (A4988, DRV8825): pin 2 = STEP, pin 3 = DIR.
AccelStepper stepper(AccelStepper::DRIVER, 2, 3);

void setup() {
  stepper.setMaxSpeed(1000);     // steps per second
  stepper.setAcceleration(500);  // steps per second^2
  stepper.moveTo(2000);          // absolute target position
}

void loop() {
  // Reverse direction when target is reached.
  if (stepper.distanceToGo() == 0) {
    stepper.moveTo(-stepper.currentPosition());
  }
  stepper.run();  // non-blocking; call as often as possible
}

