#include <Adafruit_MotorShield.h>

Adafruit_MotorShield AFMS = Adafruit_MotorShield();
Adafruit_DCMotor* myMotor = AFMS.getMotor(1);  // M1 port

void setup() {
  Serial.begin(9600);
  if (!AFMS.begin()) {
    Serial.println("Could not find Motor Shield");
    while (1);
  }
  myMotor->setSpeed(150);  // 0..255
}

void loop() {
  myMotor->run(FORWARD);
  for (int i = 0; i < 255; i++) { myMotor->setSpeed(i); delay(10); }
  for (int i = 255; i > 0; i--) { myMotor->setSpeed(i); delay(10); }

  myMotor->run(BACKWARD);
  for (int i = 0; i < 255; i++) { myMotor->setSpeed(i); delay(10); }
  for (int i = 255; i > 0; i--) { myMotor->setSpeed(i); delay(10); }

  myMotor->run(RELEASE);
  delay(1000);
}

