#include <Encoder.h>

Encoder knobLeft(2, 3);
Encoder knobRight(4, 5);

void setup() {
  Serial.begin(9600);
}

long posLeft = -999;
long posRight = -999;

void loop() {
  long newLeft  = knobLeft.read();
  long newRight = knobRight.read();

  if (newLeft != posLeft || newRight != posRight) {
    Serial.print("Left=");  Serial.print(newLeft);
    Serial.print(" Right="); Serial.println(newRight);
    posLeft  = newLeft;
    posRight = newRight;
  }

  // Reset both to zero on any serial input.
  if (Serial.available()) {
    Serial.read();
    knobLeft.write(0);
    knobRight.write(0);
  }
}

