#include <NewPing.h>

#define TRIGGER_PIN  12
#define ECHO_PIN     11
#define MAX_DISTANCE 200

NewPing sonar(TRIGGER_PIN, ECHO_PIN, MAX_DISTANCE);

void setup() {
  Serial.begin(115200);
}

void loop() {
  delay(50);
  // Median of 5 pings rejects spurious echoes.
  unsigned int us = sonar.ping_median(5);
  unsigned int cm = us / US_ROUNDTRIP_CM;
  Serial.print("Filtered distance: ");
  Serial.print(cm);
  Serial.println(" cm");
}

