#include <OneWire.h>

OneWire ds(2);  // 1-Wire bus on pin 2 (4.7k pull-up to VCC)

void setup() {
  Serial.begin(9600);
}

void loop() {
  byte addr[8];

  if (!ds.search(addr)) {
    Serial.println("No more devices.");
    ds.reset_search();
    delay(1000);
    return;
  }

  Serial.print("ROM:");
  for (byte i = 0; i < 8; i++) {
    Serial.print(' ');
    Serial.print(addr[i], HEX);
  }
  Serial.println();

  if (OneWire::crc8(addr, 7) != addr[7]) {
    Serial.println("  CRC invalid!");
    return;
  }
}

