#include <OneWire.h>

OneWire ds(2);

void setup() {
  Serial.begin(9600);
}

// Read raw scratchpad of a single DS18B20 (assumes only one on the bus).
void loop() {
  byte data[9];

  ds.reset();
  ds.skip();          // address all devices
  ds.write(0x44, 1);  // start temperature conversion
  delay(1000);        // 12-bit resolution worst case

  ds.reset();
  ds.skip();
  ds.write(0xBE);     // read scratchpad
  for (byte i = 0; i < 9; i++) data[i] = ds.read();

  int16_t raw = (data[1] << 8) | data[0];
  float celsius = raw / 16.0;
