// MQ-135 air quality sensor on A0 — print raw + ratio.
// Calibrate R0 in clean air first (see datasheet).
const int MQ135_PIN = A0;
const float RL = 10.0;        // load resistor in kOhm (board-dependent)
const float R0 = 76.63;       // <-- replace with your clean-air calibration

void setup() { Serial.begin(9600); }

void loop() {
  int raw = analogRead(MQ135_PIN);
  float vout = raw * (5.0 / 1023.0);
  float rs = (5.0 - vout) / vout * RL;
  float ratio = rs / R0;
  Serial.print("raw="); Serial.print(raw);
  Serial.print("  Rs/R0="); Serial.println(ratio, 3);
  delay(1000);
}

