// DRV8833 — drive motor A forward, then reverse, then brake.
// AIN1=5  AIN2=6  (PWM-capable pins).
const int AIN1 = 5;
const int AIN2 = 6;

void forward(int speed) { analogWrite(AIN1, speed); analogWrite(AIN2, 0); }
void reverse(int speed) { analogWrite(AIN1, 0); analogWrite(AIN2, speed); }
void brake()            { analogWrite(AIN1, 255); analogWrite(AIN2, 255); }
void coast()            { analogWrite(AIN1, 0); analogWrite(AIN2, 0); }

void setup() {
  pinMode(AIN1, OUTPUT);
  pinMode(AIN2, OUTPUT);
}

void loop() {
  forward(180); delay(1500);
  brake();      delay(500);
  reverse(180); delay(1500);
  coast();      delay(1000);
}

