// L293D — drive 2 motors (a 2WD robot chassis).
const int EN1 = 5, IN1 = 6, IN2 = 7;    // motor A
const int EN2 = 10, IN3 = 8, IN4 = 9;   // motor B

void setMotorA(int dir, int speed) {
  digitalWrite(IN1, dir > 0); digitalWrite(IN2, dir < 0);
  analogWrite(EN1, speed);
}
void setMotorB(int dir, int speed) {
  digitalWrite(IN3, dir > 0); digitalWrite(IN4, dir < 0);
  analogWrite(EN2, speed);
}

void setup() {
  for (int p : {EN1, IN1, IN2, EN2, IN3, IN4}) pinMode(p, OUTPUT);
}

void loop() {
  setMotorA(+1, 180); setMotorB(+1, 180); delay(1500); // forward
  setMotorA(-1, 180); setMotorB(-1, 180); delay(1500); // reverse
  setMotorA(0, 0);    setMotorB(0, 0);    delay(1000); // stop
}

