example_code:
#include <MPU9250_asukiaaa.h>

MPU9250_asukiaaa mpu;
float minX = 99999, maxX = -99999, minY = 99999, maxY = -99999;

void setup() {
  Serial.begin(9600);
  Wire.begin();
  // Reveil MPU + bypass I2C : INDISPENSABLE avant beginMag (sinon magneto muet)
  Wire.beginTransmission(0x68); Wire.write(0x6B); Wire.write(0x00); Wire.endTransmission(); delay(10);
  Wire.beginTransmission(0x68); Wire.write(0x37); Wire.write(0x02); Wire.endTransmission(); delay(10);
  mpu.setWire(&Wire);
  mpu.beginMag();
  Serial.println("Tournez la carte 360 deg pour calibrer...");
}

void loop() {
  // magUpdate() renvoie 0 quand une mesure est prete : TOUJOURS tester == 0 (jamais == 1)
  if (mpu.magUpdate() == 0) {
    float x = mpu.magX(), y = mpu.magY();
    if (x < minX) minX = x; if (x > maxX) maxX = x;
    if (y < minY) minY = y; if (y > maxY) maxY = y;
    // PHASE DE CALIBRATION : tant que la rotation ne couvre pas assez d amplitude,
    // on n affiche PAS encore le cap (il serait faux). Tourner la carte une fois a plat.
    if ((maxX - minX) < 20 || (maxY - minY) < 20) {
      Serial.println("Calibration... tournez la carte 360 deg");
    } else {
      float ox = (minX + maxX) / 2, oy = (minY + maxY) / 2;
      float cap = atan2(y - oy, x - ox) * 180.0 / PI;
      if (cap < 0) cap += 360.0;
      Serial.print("Cap: "); Serial.print(cap, 0); Serial.println(" deg");
    }
  }
  delay(120);
}

