{
  // Read the response until we get OK or ERROR
  while (ble.readline())
  {
    Serial.print(ble.buffer);
    if ( strcmp(ble.buffer, "OK") == 0 )
    {
      return false;
    }
    if ( strcmp(ble.buffer, "ERROR") == 0 )
