// MH-Z14A : lecture du CO2 en UART via SoftwareSerial.
#include <SoftwareSerial.h>

SoftwareSerial co2Serial(10, 11);  // RX Arduino <- TX capteur
const byte DEMANDE[9] = {0xFF, 0x01, 0x86, 0, 0, 0, 0, 0, 0x79};

void setup() {
  Serial.begin(9600);
  co2Serial.begin(9600);
}

void loop() {
  co2Serial.write(DEMANDE, 9);
  byte reponse[9];
  if (co2Serial.readBytes(reponse, 9) == 9 && reponse[0] == 0xFF) {
    int ppm = reponse[2] * 256 + reponse[3];
    Serial.print("CO2: "); Serial.print(ppm); Serial.println(" ppm");
  }
  delay(2000);
}

