// RCWL-1005 : mesure de distance en I2C.
#include <Wire.h>

const byte ADRESSE = 0x57;

void setup() {
  Serial.begin(9600);
  Wire.begin();
}

void loop() {
  Wire.beginTransmission(ADRESSE);
  Wire.write(0x01);            // demander une mesure
  Wire.endTransmission();
  delay(120);
  Wire.requestFrom(ADRESSE, (byte)3);
  if (Wire.available() == 3) {
    long um = ((long)Wire.read() << 16) | ((long)Wire.read() << 8) | Wire.read();
    Serial.print("Distance: "); Serial.print(um / 1000.0, 1);
    Serial.println(" mm");
  }
  delay(500);
}

