// JSN-SR04T : impulsion de 10 us sur TRIG, mesure sur ECHO.
const int TRIG_PIN = 9;
const int ECHO_PIN = 10;

void setup() {
  Serial.begin(9600);
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
}

void loop() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);
  long duree = pulseIn(ECHO_PIN, HIGH);
  float cm = duree * 0.0343 / 2.0;
  Serial.print("Distance: "); Serial.print(cm, 1);
  Serial.println(" cm");
  delay(500);
}
